                    z[i] = np.random.normal(0, 1)
                else:
                    z[i] = -np.random.normal(0, 1)
            cov += np.outer(z, z)

    mean = np.zeros(dim)
    cov = np.eye(dim)
    x_best = None
    f_x_best = float('inf')

    for i in range(budget):
